corrected_code:
package handlers

import (
	"net/http"

	"github.com/gorilla/mux"
	"myapp/auth"
	"myapp/preferences"
)

type NotificationController struct {
	PrefStore preferences.Store
}

func (c *NotificationController) SetDigestFrequency(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	profileID := vars["profileID"]
	sessionUser := auth.GetSessionUser(r.Context())

	if sessionUser.ProfileID != profileID {
		http.Error(w, "Unauthorized profile modification", http.StatusForbidden)
		return
	}

	freq := r.URL.Query().Get("freq")
	err := c.PrefStore.UpdateDigest(r.Context(), profileID, freq)
	if err != nil {
		http.Error(w, "Update failed", http.StatusBadRequest)
		return
	}

	w.WriteHeader(http.StatusOK)
}
